"""
Global Jurisdictional Document Requirements Matrix.
Defines required, conditional, and supplemental documents by jurisdiction and legal entity structure.
"""

from dataclasses import dataclass
from typing import Dict, List, Optional

@dataclass
class DocumentRequirement:
    code: str
    title: str
    description: str
    is_mandatory: bool
    validity_days: int  # 0 if perpetual until material change
    requires_certified_true_copy: bool
    requires_apostille: bool
    applies_to_entity_types: List[str]
    applies_to_jurisdictions: List[str]

